/* eslint-disable no-nested-ternary */
import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Divider,
  Grid,
  LinearProgress,
  MenuItem,
  Select,
  Stack,
  Typography,
  useMediaQuery,
  useTheme,
  Snackbar,
  Alert,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from '@mui/material';
import { Icon } from '@iconify/react';
import { useTranslation } from 'react-i18next';
import confetti from 'canvas-confetti';
import { m, AnimatePresence } from 'framer-motion';

import {
  listActiveRafs,
  getRoundState,
  buyNumbers,
  RafSummary,
  RoundState,
  toUiPhase,
} from 'src/redux/slices/raf';
import { useSelector, useDispatch } from 'src/redux/store';
import { getWallet } from 'src/redux/slices/wallet';
import { fCurrency } from 'src/utils/format-number';

/* ===== Helpers ===== */
const pad = (n: number) => String(n).padStart(2, '0');
const makeBalls = (count: number) => Array.from({ length: count }, (_, i) => pad(i));

/* ===== Page ===== */
export default function RafPage() {
  const { t } = useTranslation();
  const [rafList, setRafList] = useState<RafSummary[] | null>(null);
  const [chosen, setChosen] = useState<RafSummary | null>(null);
  const [error, setError] = useState<string | null>(null);
  const dispatch = useDispatch();

  const { wallet } = useSelector((s) => s.wallet);
  const [loading, setLoading] = useState<boolean>(false);

  useEffect(() => {
    dispatch(getWallet());
  }, [dispatch]);

  // load lobby + wallet
  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        setLoading(true);
        const list = await listActiveRafs();
        if (!mounted) return;
        setRafList(list);
      } catch (e: any) {
        setError(e?.response?.data?.message || e.message || t('network_error'));
      } finally {
        setLoading(false);
      }
    })();
    return () => {
      mounted = false;
    };
  }, [t]);

  return chosen ? (
    <RafGame chosen={chosen} onBack={() => setChosen(null)} onError={(msg) => setError(msg)} />
  ) : (
    <Lobby
      list={rafList}
      loading={loading}
      onChoose={(s) => setChosen(s)}
      error={error}
      onError={setError}
    />
  );
}

/* ===== Lobby ===== */
function Lobby({
  list,
  loading,
  onChoose,
  error,
  onError,
}: {
  list: RafSummary[] | null;
  loading: boolean;
  onChoose: (s: RafSummary) => void;
  error: string | null;
  onError: (m: string | null) => void;
}) {
  const { t } = useTranslation();
  const { wallet } = useSelector((s) => s.wallet);
  return (
    <Box sx={{ minHeight: '100vh', bgcolor: '#0c1420', color: '#fff', p: 2 }}>
      <Stack
        direction="row"
        alignItems="center"
        spacing={1}
        sx={{ mb: 2, justifyContent: 'center' }}
      >
        <Icon icon="solar:gamepad-bold" fontSize={26} />
        <Typography variant="h5" fontWeight={800}>
          {t('choose_session')}
        </Typography>
      </Stack>

      <Box sx={{ maxWidth: 1080, mx: 'auto' }}>
        <Grid container spacing={2} justifyContent="center">
          {loading && (
            <Grid item xs={12}>
              <LinearProgress />
            </Grid>
          )}

          {!loading && list?.length === 0 && (
            <Grid item xs={12}>
              <Card sx={{ bgcolor: '#0f1e32', border: '1px solid #1e2f4a' }}>
                <CardContent>
                  <Typography sx={{ color: 'white' }}>{t('no_active_sessions')}</Typography>
                </CardContent>
              </Card>
            </Grid>
          )}

          {(list ?? []).map((s) => {
            const phase = toUiPhase(s.status);
            return (
              <Grid key={s.round_code} item xs={12} sm={6} md={4}>
                <Card
                  sx={{
                    bgcolor: '#0f1e32',
                    border: '1px solid #1e2f4a',
                    height: '100%',
                    position: 'relative',
                  }}
                >
                  <CardContent>
                    <Stack spacing={1.2}>
                      <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
                        <Chip
                          icon={<Icon icon="solar:star-fall-bold" />}
                          label={s.raf_name}
                          sx={{ bgcolor: '#152238', color: '#fff', fontWeight: 700 }}
                        />
                        <Chip
                          icon={<Icon icon="solar:wallet-bold" />}
                          label={
                            s.type === 'paid'
                              ? t('stake_amount', {
                                  amount: fCurrency(s.stake, false),
                                  currency: wallet?.currency,
                                })
                              : t('free_session')
                          }
                          sx={{ bgcolor: '#152238', color: '#fff' }}
                        />
                      </Stack>
                      <Stack direction="row" spacing={1} flexWrap="wrap">
                        <Chip
                          icon={<Icon icon="solar:percent-bold" />}
                          label={t('payouts_list', { list: s.payoutsMultipliers.join(' / ') })}
                          sx={{ bgcolor: '#1b2c46', color: '#fff' }}
                        />
                        <Chip
                          icon={<Icon icon="solar:clock-circle-bold" />}
                          label={t('after_sell_delay', { minutes: s.postSellDelayMin })}
                          sx={{ bgcolor: '#1b2c46', color: '#fff' }}
                        />
                        <Chip
                          icon={<Icon icon="solar:users-group-two-rounded-bold" />}
                          label={t('sold_of_total', { sold: s.sold, total: s.ballsCount })}
                          sx={{ bgcolor: '#1b2c46', color: '#fff' }}
                        />
                        <Chip
                          icon={<Icon icon="solar:flag-2-bold" />}
                          label={
                            phase === 'finished'
                              ? t('status_finished')
                              : phase === 'waiting'
                                ? t('status_waiting')
                                : phase === 'drawing'
                                  ? t('status_drawing')
                                  : t('status_selling')
                          }
                          sx={{ bgcolor: '#1b2c46', color: '#fff' }}
                        />
                      </Stack>
                      <Divider sx={{ borderColor: '#274063' }} />
                      <Button
                        fullWidth
                        variant="contained"
                        onClick={() => onChoose(s)}
                        startIcon={
                          <Icon
                            icon={
                              ['finished', 'waiting', 'drawing']?.includes(phase)
                                ? 'stash:trophy'
                                : 'solar:play-bold'
                            }
                          />
                        }
                        sx={(theme) =>
                          ['finished', 'waiting', 'drawing']?.includes(phase)
                            ? {
                                background: 'linear-gradient(135deg, #f59e0b, #fcd34d)',
                                color: '#1f1724',
                                fontWeight: 900,
                                boxShadow: 'none',
                                '&:hover': {
                                  background: 'linear-gradient(135deg, #f59e0b, #fbbf24)',
                                },
                              }
                            : {
                                background: `linear-gradient(135deg, ${theme.palette.primary.light}, ${theme.palette.primary.main})`,
                                color: '#05211a',
                                fontWeight: 900,
                                boxShadow: 'none',
                                '&:hover': {
                                  background: `linear-gradient(135deg, ${theme.palette.primary.main}, ${theme.palette.primary.dark})`,
                                },
                              }
                        }
                      >
                        {['finished', 'waiting', 'drawing']?.includes(phase)
                          ? t('button_view_results')
                          : t('button_play')}
                      </Button>
                    </Stack>
                  </CardContent>
                </Card>
              </Grid>
            );
          })}
        </Grid>
      </Box>

      <Snackbar open={!!error} autoHideDuration={4000} onClose={() => onError(null)}>
        <Alert severity="error" onClose={() => onError(null)}>
          {error}
        </Alert>
      </Snackbar>
    </Box>
  );
}

/* ===== Game ===== */
type Owner = null | 'me' | 'other';
interface Cell {
  n: string;
  owner: Owner;
}

function RafGame({
  chosen,
  onBack,
  onError,
}: {
  chosen: RafSummary;
  onBack: () => void;
  onError: (m: string) => void;
}) {
  const { t } = useTranslation();
  const dispatch = useDispatch();
  const { wallet } = useSelector((s) => s.wallet);
  const theme = useTheme();
  const isXs = useMediaQuery(theme.breakpoints.down('sm'));
  const isMd = useMediaQuery(theme.breakpoints.down('md'));
  const desktop = !isMd;

  const cellH = isXs ? 42 : isMd ? 52 : 50;
  const fontSz = isXs ? 11 : isMd ? 13 : 13;
  const columnsCount = desktop ? 10 : 10;
  const gridSpacing = desktop ? 0.8 : isXs ? 0.6 : 1.0;
  const br = isXs ? '12px' : desktop ? '16px' : '18px';
  const brInner = isXs ? '9px' : desktop ? '12px' : '14px';

  const [state, setState] = useState<RoundState | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [toast, setToast] = useState<{ type: 'success' | 'error'; msg: string } | null>(null);

  const roundCode = chosen.round_code;
  const ballsCount = state?.raf.ballsCount ?? chosen.ballsCount;
  const isPaid = (state?.raf.type ?? chosen.type) === 'paid';
  const stake = state?.raf.stake ?? chosen.stake;
  const limitPerUser = state?.raf.limitPerUser ?? chosen.limitPerUser;
  const payouts = state?.raf.payoutsMultipliers ?? chosen.payoutsMultipliers;
  const BALLS = useMemo(() => makeBalls(ballsCount), [ballsCount]);

  // construire la grille
  const board: Cell[] = useMemo(() => {
    if (!state) return BALLS.map((b) => ({ n: b, owner: null }));
    const mine = new Set(state.purchased.mine);
    const all = new Set(state.purchased.all);
    return BALLS.map((n) =>
      mine.has(n) ? { n, owner: 'me' } : all.has(n) ? { n, owner: 'other' } : { n, owner: null }
    );
  }, [BALLS, state]);

  const phase: 'selling' | 'waiting' | 'drawing' | 'finished' = !state
    ? toUiPhase(chosen.status)
    : state.status === 'ongoing'
      ? 'selling'
      : state.status === 'waiting'
        ? 'waiting'
        : state.status === 'drawing'
          ? 'drawing'
          : 'finished';

  const myTickets = state?.purchased.mine ?? [];
  const results = state?.results ?? null;
  const winners = results ? [results.result_1, results.result_2, results.result_3] : [];
  const winsState = {
    main: !!results && myTickets.includes(results.result_1),
    second: !!results && myTickets.includes(results.result_2),
    third: !!results && myTickets.includes(results.result_3),
  };
  const lost = !!results && !winsState.main && !winsState.second && !winsState.third;

  // remaining for free limit
  const remainingAllowed = useMemo(() => {
    if (!state) return Infinity;
    const limit = state.raf.limitPerUser;
    if (state.raf.type === 'free' && typeof limit === 'number') {
      return Math.max(0, limit - myTickets.length);
    }
    return Infinity;
  }, [state, myTickets.length]);

  const sold = state?.sold ?? chosen.sold;
  const progressValue = Math.min(100, Math.max(0, (sold / ballsCount) * 100));

  // load state
  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        const s = await getRoundState(roundCode);
        if (!mounted) return;
        setState(s);
      } catch (e: any) {
        onError(e?.response?.data?.message || e.message || t('generic_error'));
      }
    })();
    return () => {
      mounted = false;
    };
  }, [roundCode, onError, t]);

  // polling
  const pollRef = useRef<number | null>(null);
  useEffect(() => {
    if (!state) return;
    if (phase === 'finished') {
      if (pollRef.current) window.clearInterval(pollRef.current);
      pollRef.current = null;
      return;
    }
    if (pollRef.current) window.clearInterval(pollRef.current);
    pollRef.current = window.setInterval(async () => {
      try {
        const s = await getRoundState(roundCode);
        setState(s);
      } catch {}
    }, 2500) as any;
    return () => {
      if (pollRef.current) window.clearInterval(pollRef.current);
      pollRef.current = null;
    };
  }, [state?.status, phase, roundCode]);

  const refreshWallet = async () => {
    try {
      dispatch(getWallet());
    } catch {}
  };

  async function handleBuy() {
    if (!state) return;
    const list = Array.from(selected).filter((n) => {
      const c = board.find((x) => x.n === n);
      return c && c.owner === null;
    });

    if (remainingAllowed !== Infinity && list.length > remainingAllowed) {
      setToast({ type: 'error', msg: t('limit_reached_free') });
      return;
    }
    if (list.length === 0) return;

    try {
      await buyNumbers({ raf_id: state.raf.id, round_code: state.round_code, numbers: list });
      setSelected(new Set());
      setToast({ type: 'success', msg: t('purchase_success', { count: list.length }) });
      await Promise.all([refreshWallet(), getRoundState(state.round_code).then(setState)]);
    } catch (e: any) {
      setToast({
        type: 'error',
        msg: e?.response?.data?.message || e.message || t('purchase_error'),
      });
    }
  }

  type UiPhase = 'selling' | 'waiting' | 'drawing' | 'finished';
  const THEME_HUD: Record<UiPhase, string> = {
    selling: 'primary.dark',
    waiting: '#ffd45e',
    drawing: '#9cf',
    finished: '#7ee287',
  };
  const themeHud = THEME_HUD[phase];

  return (
    <Box
      sx={{
        minHeight: '100vh',
        bgcolor: '#0c1420',
        color: 'white',
        p: { xs: 1.25, sm: 2 },
        position: 'relative',
      }}
    >
      <Box sx={{ maxWidth: 1100, mx: 'auto' }}>
        {/* HUD */}
        <Stack
          direction={{ xs: 'column', md: 'row' }}
          alignItems={{ xs: 'stretch', md: 'center' }}
          spacing={1.2}
          sx={{ mb: { xs: 2, md: 1.25 } }}
        >
          <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
            <Button
              onClick={onBack}
              startIcon={<Icon icon="solar:alt-arrow-left-bold" />}
              sx={{ bgcolor: '#10223a', color: '#9ec8ff' }}
            >
              {t('sessions')}
            </Button>
            <Chip
              icon={<Icon icon="solar:gamepad-bold" />}
              label={chosen.raf_name}
              sx={{ bgcolor: '#152238', color: 'white', fontWeight: 700 }}
            />
            <Chip
              icon={<Icon icon="solar:wallet-bold" />}
              label={
                isPaid
                  ? t('stake_paid', { amount: fCurrency(stake, false), currency: wallet?.currency })
                  : t('free_session')
              }
              sx={{ bgcolor: '#152238', color: 'white' }}
            />
            <Chip
              icon={<Icon icon="solar:clock-circle-bold" />}
              label={
                phase === 'waiting'
                  ? t('hud_waiting_draw')
                  : phase === 'selling'
                    ? t('hud_selling')
                    : phase === 'drawing'
                      ? t('hud_drawing')
                      : t('hud_finished')
              }
              sx={{ bgcolor: themeHud, color: '#061018', fontWeight: 700 }}
            />
          </Stack>

          <Box flexGrow={1} />

          <Stack
            direction="row"
            spacing={1}
            alignItems="center"
            justifyContent={{ xs: 'space-between', md: 'flex-end' }}
          >
            {/* <Select
              size="small"
              value={chosen.round_code}
              sx={{
                bgcolor: '#0f1e32',
                color: 'white',
                '.MuiOutlinedInput-notchedOutline': { borderColor: '#21324c' },
                maxWidth: 260,
              }}
            >
              <MenuItem value={chosen.round_code}>
                {chosen.raf_name} • {t('round_short', { code: chosen.round_code.slice(0, 6) })}
              </MenuItem>
            </Select> */}
            <Chip
              icon={<Icon icon="solar:percent-bold" />}
              label={t('payouts_list', { list: payouts.join(' / ') })}
              sx={{ bgcolor: '#152238', color: 'white' }}
            />
            <Chip
              icon={<Icon icon="solar:settings-bold" />}
              label={limitPerUser ? t('limit_label', { n: limitPerUser }) : t('no_limit')}
              sx={{ bgcolor: '#152238', color: 'white' }}
            />
          </Stack>
        </Stack>

        {/* Progress */}
        <Box sx={{ maxWidth: 900, mx: 'auto' }}>
          <LinearProgress
            variant="determinate"
            value={progressValue}
            sx={{
              height: { xs: 8, md: 10 },
              borderRadius: 999,
              bgcolor: '#0f1e32',
              '& .MuiLinearProgress-bar': { bgcolor: 'primary.main' },
              mb: 2,
            }}
          />
        </Box>

        {/* DRAW or GRID */}
        {phase !== 'selling' ? (
          <Card
            sx={{
              bgcolor: '#0f1e32',
              border: '1px solid #1e2f4a',
              boxShadow: '0 0 30px rgba(0,0,0,.5) inset',
              maxWidth: 900,
              mx: 'auto',
            }}
          >
            <CardContent>
              <Stack alignItems="center" spacing={3} sx={{ py: { xs: 2, md: 3 } }}>
                <Typography
                  component={m.div}
                  initial={{ y: 8, opacity: 0 }}
                  animate={{
                    y: 0,
                    opacity: 1,
                    transition: { type: 'spring', stiffness: 300, damping: 20 },
                  }}
                  variant={isXs ? 'h6' : 'h5'}
                  fontWeight={800}
                  sx={{ color: 'white' }}
                >
                  {t('draw_title')}{' '}
                  {phase === 'waiting' && (
                    <Icon icon="solar:loading-dots-linear" style={{ marginLeft: 8 }} />
                  )}
                </Typography>

                {/* —— Tirage magique avec animations —— */}
                <DrawMagic winners={winners} payouts={payouts} phase={phase} />

                {/* Résumé win/lose */}
                {(phase === 'finished' || results) && (
                  <Stack direction="row" spacing={1} flexWrap="wrap" justifyContent="center">
                    {winsState.main && (
                      <Chip
                        color="success"
                        label={t('chip_win_main', { stake: stake, mult: payouts[0] })}
                      />
                    )}
                    {winsState.second && (
                      <Chip
                        color="info"
                        label={t('chip_win_second', { stake: stake, mult: payouts[1] })}
                      />
                    )}
                    {winsState.third && (
                      <Chip
                        color="warning"
                        label={t('chip_win_third', { stake: stake, mult: payouts[2] })}
                      />
                    )}
                    {lost && (
                      <Chip
                        icon={<Icon icon="solar:emoji-sad-bold" />}
                        label={t('not_lucky')}
                        sx={{ bgcolor: '#182435', color: '#ff9aa2', border: '1px solid #ff9aa244' }}
                      />
                    )}
                  </Stack>
                )}

                {/* Winners List (même user possible plusieurs fois) */}
                {(phase === 'finished' || results) && (
                  <WinnersList results={results} payouts={payouts} stake={stake} isPaid={isPaid} />
                )}
              </Stack>
            </CardContent>
          </Card>
        ) : (
          <>
            {/* GRID */}
            <Card
              sx={{
                bgcolor: '#0f1e32',
                border: '1px solid #1e2f4a',
                boxShadow: '0 0 30px rgba(0,0,0,.5) inset',
                maxWidth: 900,
                mx: 'auto',
              }}
            >
              <CardContent sx={{ p: { xs: 0.8, sm: 1.6, md: 1.25 }, pb: '10px !important' }}>
                <Grid
                  container
                  spacing={gridSpacing}
                  columns={columnsCount}
                  justifyContent="center"
                >
                  {board.map((cell, idx) => {
                    const isMine = cell.owner === 'me';
                    const isOther = cell.owner === 'other';
                    const available = cell.owner === null;
                    const selectedHere = selected.has(cell.n);
                    const bg = isMine ? '#2bd67b' : isOther ? '#7a8699' : '#2f8fff';
                    const dim = !available && !isMine ? 0.55 : 1;

                    return (
                      <Grid key={cell.n} item xs={1}>
                        <Box
                          onClick={() => {
                            if (!available) return;
                            setSelected((prev) => {
                              const next = new Set(prev);
                              if (next.has(cell.n)) {
                                next.delete(cell.n);
                                return next;
                              }
                              if (remainingAllowed !== Infinity && next.size + 1 > remainingAllowed)
                                return next;
                              next.add(cell.n);
                              return next;
                            });
                          }}
                          sx={{
                            height: cellH,
                            borderRadius: br,
                            display: 'grid',
                            placeItems: 'center',
                            cursor: available ? 'pointer' : 'not-allowed',
                            background:
                              selectedHere && available
                                ? `linear-gradient(180deg, ${bg}, #123a66)`
                                : `linear-gradient(180deg, #0b1a2b, #0a1522)`,
                            border: selectedHere ? `2px solid ${bg}` : '2px solid #254566',
                            boxShadow: selectedHere
                              ? `0 0 18px ${bg}88, inset 0 0 26px rgba(20,40,80,.8)`
                              : 'inset 0 0 24px rgba(20,40,80,.8)',
                            position: 'relative',
                            transition: 'all .18s ease',
                            opacity: dim,
                            '&:hover': {
                              transform: available ? 'translateY(-3px) scale(1.02)' : 'none',
                            },
                            color: isMine ? 'primary.dark' : isOther ? '#ffffff' : '#cfe4ff',
                            animation: 'pop .35s ease backwards',
                            animationDelay: `${(idx % 9) * 0.01}s`,
                          }}
                        >
                          <Typography fontWeight={800} fontSize={fontSz}>
                            {cell.n}
                          </Typography>
                          <Box
                            sx={{
                              position: 'absolute',
                              inset: 3,
                              borderRadius: brInner,
                              boxShadow: `0 0 18px ${
                                isMine ? '#2bd67b55' : isOther ? '#ffffff18' : '#2f8fff33'
                              }`,
                              pointerEvents: 'none',
                            }}
                          />
                          {isMine && (
                            <Icon
                              icon="solar:check-circle-bold"
                              style={{ position: 'absolute', right: 4, bottom: 4, fontSize: 14 }}
                            />
                          )}
                        </Box>
                      </Grid>
                    );
                  })}
                </Grid>
                <style>{`@keyframes pop{0%{transform:scale(.92);opacity:.0}100%{transform:scale(1);opacity:1}}`}</style>
              </CardContent>
            </Card>

            {/* ACTIONS */}
            <Box sx={{ maxWidth: 900, mx: 'auto' }}>
              <Stack
                direction={{ xs: 'column', md: 'row' }}
                spacing={1.2}
                sx={{ mt: 2 }}
                alignItems="stretch"
              >
                <Card sx={{ flex: 1, bgcolor: '#0f1e32', border: '1px solid #1e2f4a' }}>
                  <CardContent sx={{ p: { xs: 1.2, sm: 2 } }}>
                    <Stack
                      alignItems={{ xs: 'stretch', sm: 'center' }}
                      justifyContent="space-between"
                      spacing={1.2}
                    >
                      <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
                        <Chip
                          icon={<Icon icon="solar:bag-4-bold" />}
                          label={t('to_pay', {
                            amount: fCurrency(stake * selected.size, false),
                            currency: wallet?.currency,
                          })}
                          sx={{ bgcolor: '#1b2c46', color: 'white', fontWeight: 700 }}
                        />
                        <Divider
                          flexItem
                          orientation="vertical"
                          sx={{ display: { xs: 'none', sm: 'block' }, borderColor: '#28476e' }}
                        />
                        <Button
                          variant="contained"
                          startIcon={<Icon icon="solar:cart-5-bold" />}
                          disabled={selected.size === 0 || remainingAllowed === 0}
                          onClick={handleBuy}
                          sx={{
                            background:
                              selected.size > 0
                                ? 'linear-gradient(135deg, #2bd67b, #6ee7b7)'
                                : '#3a5a80',
                            color: '#06202a',
                            fontWeight: 900,
                            minWidth: 140,
                            ':disabled': { background: '#314966', color: '#96a5b6' },
                          }}
                        >
                          {selected.size ? t('buy_with_count', { count: selected.size }) : t('buy')}
                        </Button>
                        <Button
                          variant="outlined"
                          startIcon={<Icon icon="solar:refresh-bold" />}
                          onClick={() => setSelected(new Set())}
                          sx={{
                            borderColor: '#355781',
                            color: 'white',
                            ':hover': { borderColor: '#5a8ad1' },
                          }}
                        >
                          {t('reset_selection')}
                        </Button>
                      </Stack>
                      <Stack direction="row" spacing={1}>
                        <MyNumbersPreview
                          numbers={Array.from(selected).sort()}
                          chipTitle={t('my_numbers')}
                        />
                      </Stack>
                      {remainingAllowed !== Infinity && remainingAllowed === 0 && (
                        <Typography variant="caption" sx={{ color: '#ff9aa2' }}>
                          {t('limit_reached_free')}
                        </Typography>
                      )}
                    </Stack>
                  </CardContent>
                </Card>
              </Stack>
            </Box>
          </>
        )}
      </Box>

      <Snackbar open={Boolean(toast)} autoHideDuration={3000} onClose={() => setToast(null)}>
        {toast ? (
          <Alert severity={toast.type} onClose={() => setToast(null)} sx={{ width: '100%' }}>
            {toast.msg}
          </Alert>
        ) : undefined}
      </Snackbar>
    </Box>
  );
}

/* ====== Mes numéros (dialog) ====== */
function MyNumbersPreview({
  numbers,
  chipTitle = 'Mes numéros',
}: {
  numbers: string[];
  chipTitle?: string;
}) {
  const { t } = useTranslation();
  const theme = useTheme();
  const isXs = useMediaQuery(theme.breakpoints.down('sm'));
  const MAX_INLINE = isXs ? 8 : 15;
  const [open, setOpen] = React.useState(false);

  const hasAny = numbers && numbers.length > 0;
  const preview = hasAny ? numbers.slice(0, MAX_INLINE).join(' • ') : '—';
  const rest = Math.max(0, (numbers?.length || 0) - MAX_INLINE);

  return (
    <>
      <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
        <Chip
          icon={<Icon icon="solar:ticket-bold" />}
          label={`${chipTitle}: ${preview}`}
          sx={{ bgcolor: '#1b2c46', color: 'white' }}
        />
        {rest > 0 && (
          <Chip
            clickable
            onClick={() => setOpen(true)}
            label={t('others_more', { count: rest })}
            sx={{ bgcolor: '#233754', color: 'white', '&:hover': { bgcolor: '#294062' } }}
          />
        )}
      </Stack>

      <Dialog open={open} onClose={() => setOpen(false)} fullWidth maxWidth="sm">
        <DialogTitle>
          <Stack direction="row" alignItems="center" justifyContent="space-between">
            <Typography fontWeight={800}>
              {t('my_numbers_count_title', { count: numbers.length })}
            </Typography>
          </Stack>
        </DialogTitle>
        <DialogContent dividers>
          <Box
            sx={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(56px, 1fr))',
              gap: 1,
            }}
          >
            {numbers.map((n) => (
              <Box
                key={n}
                sx={{
                  height: 40,
                  borderRadius: 1,
                  bgcolor: '#0f1e32',
                  border: '1px solid #1e2f4a',
                  display: 'grid',
                  placeItems: 'center',
                  color: '#cfe4ff',
                  fontWeight: 800,
                  letterSpacing: 0.5,
                }}
              >
                {n}
              </Box>
            ))}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpen(false)} variant="contained">
            {t('close')}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
}

/* ====== Winners list ====== */
function WinnersList({
  results,
  payouts,
  stake,
  isPaid,
}: {
  results: RoundState['results'] | null;
  payouts: number[];
  stake: number;
  isPaid: boolean;
}) {
  const { t } = useTranslation();
  const wallet = useSelector((s) => s.wallet.wallet);

  if (!results) return null;

  // 1er/2e/3e (même user peut apparaître plusieurs fois)
  const rankBalls: Array<{ ball: string | null; rank: number }> = [
    { ball: results.result_1 ?? null, rank: 0 },
    { ball: results.result_2 ?? null, rank: 1 },
    { ball: results.result_3 ?? null, rank: 2 },
  ];

  const userByBall = new Map<string, string>();
  if (Array.isArray((results as any)?.wins)) {
    for (const w of (results as any).wins as Array<{ ball: string; user: string }>) {
      if (w?.ball) userByBall.set(w.ball, w.user || t('anonymous_user'));
    }
  }

  const items = rankBalls
    .filter((x) => !!x.ball)
    .map(({ ball, rank }) => {
      const b = String(ball);
      const name = userByBall.get(b) || t('anonymous_user');
      const mult = payouts[rank] ?? 0;
      const payout = stake * mult;
      return { ball: b, rank, name, mult, payout };
    });

  if (!items.length) return null;

  return (
    <Box sx={{ width: '100%', maxWidth: 900, mx: 'auto' }}>
      <Typography
        variant="subtitle1"
        sx={{ color: '#cfe4ff', mb: 1, fontWeight: 700, textAlign: 'center', width: '100%' }}
      >
        {t('winners_title')}
      </Typography>

      <Grid container spacing={1.2} justifyContent="center">
        {items.map((it) => {
          const ring = it.rank === 0 ? '#2bd67b' : it.rank === 1 ? '#84b6ff' : '#ffd66b';
          const badge =
            it.rank === 0 ? t('rank_first') : it.rank === 1 ? t('rank_second') : t('rank_third');

          return (
            <Grid key={`${it.ball}:${it.rank}`} item xs={12} sm={10} md={8}>
              <Box
                sx={{
                  p: 1.2,
                  borderRadius: 2.5,
                  bgcolor: '#0b1624',
                  border: `1px solid ${ring}55`,
                  boxShadow: `0 0 0 1px ${ring}22, 0 10px 30px ${ring}22, inset 0 0 40px ${ring}11`,
                }}
              >
                <Box
                  sx={{
                    p: { xs: 1.2, sm: 1.6 },
                    borderRadius: 2,
                    background:
                      it.rank === 0
                        ? 'linear-gradient(135deg, #0e2b1f 0%, #1d3f33 60%, #0e2b1f 100%)'
                        : it.rank === 1
                          ? 'linear-gradient(135deg, #0e1d2b 0%, #1a3250 60%, #0e1d2b 100%)'
                          : 'linear-gradient(135deg, #2b240e 0%, #534218 60%, #2b240e 100%)',
                    position: 'relative',
                    overflow: 'hidden',
                  }}
                >
                  <Stack
                    direction={{ xs: 'column', sm: 'row' }}
                    spacing={1.2}
                    alignItems={{ xs: 'flex-start', sm: 'center' }}
                    justifyContent="space-between"
                  >
                    <Stack direction="row" spacing={1.2} alignItems="center" flexWrap="wrap">
                      <Icon
                        icon={
                          it.rank === 0
                            ? 'solar:crown-bold'
                            : it.rank === 1
                              ? 'solar:medal-ribbons-star-bold-duotone'
                              : 'solar:medal-star-bold'
                        }
                        fontSize={22}
                        color={ring}
                        style={{ filter: 'drop-shadow(0 2px 8px rgba(0,0,0,.35))' }}
                      />
                      <Typography variant="h6" fontWeight={900} sx={{ color: 'white' }}>
                        {it.name}
                      </Typography>
                      <Chip
                        size="small"
                        label={`#${it.ball}`}
                        sx={{ bgcolor: '#0e2238', color: '#cfe4ff', border: `1px solid ${ring}55` }}
                      />
                      <Chip
                        size="small"
                        label={`${badge} • x${it.mult}`}
                        sx={{ bgcolor: ring, color: '#072018', fontWeight: 900 }}
                      />
                    </Stack>

                    <Stack alignItems={{ xs: 'flex-start', sm: 'flex-end' }}>
                      <Typography fontSize={12} sx={{ opacity: 0.7, mb: 0.25, color: 'white' }}>
                        {t('gain_label')}
                      </Typography>
                      <Typography variant="h5" fontWeight={900} sx={{ color: 'white' }}>
                        {`${fCurrency(it.payout, false)} ${wallet?.currency}`}
                      </Typography>
                    </Stack>
                  </Stack>
                </Box>
              </Box>
            </Grid>
          );
        })}
      </Grid>
    </Box>
  );
}

/* ====== Tirage magique (animations) ====== */
function DrawMagic({
  winners,
  payouts,
  phase,
}: {
  winners: (string | null)[];
  payouts: number[];
  phase: 'selling' | 'waiting' | 'drawing' | 'finished';
}) {
  const [fired, setFired] = React.useState(false);

  // 🎉 Confetti quand on a les 3 résultats
  React.useEffect(() => {
    const ready = winners.filter(Boolean).length === 3 && phase === 'finished';
    if (ready && !fired && typeof window !== 'undefined') {
      setFired(true);
      confetti({ particleCount: 120, spread: 70, origin: { x: 0.15, y: 0.2 } });
      confetti({ particleCount: 120, spread: 70, origin: { x: 0.85, y: 0.2 } });
      setTimeout(() => confetti({ particleCount: 80, spread: 90, origin: { y: 0.3 } }), 300);
    }
  }, [winners, phase, fired]);

  return (
    <Stack
      direction="row"
      spacing={{ xs: 1, md: 2 }}
      alignItems="center"
      justifyContent="center"
      flexWrap="wrap"
      sx={{ position: 'relative' }}
    >
      {[0, 1, 2].map((i) => (
        <AnimatedBall
          key={i}
          index={i}
          value={winners[i] ?? null}
          mult={payouts[i] ?? 0}
          ringColor={i === 0 ? '#2bd67b' : i === 1 ? '#84b6ff' : '#ffd66b'}
          loading={phase === 'waiting' || phase === 'drawing'}
        />
      ))}

      {/* keyframes globaux */}
      <style>{`
        @keyframes spin { from { transform: rotate(0deg) } to { transform: rotate(360deg) } }
        @keyframes pulse { 0% { opacity:.7; filter: drop-shadow(0 0 0px rgba(255,255,255,.0)); }
                           50% { opacity:1; filter: drop-shadow(0 0 10px rgba(255,255,255,.35)); }
                           100% { opacity:.7; filter: drop-shadow(0 0 0px rgba(255,255,255,.0)); } }
        @keyframes shine { from { background-position: -200% 0; } to { background-position: 200% 0; } }
      `}</style>
    </Stack>
  );
}

function AnimatedBall({
  index,
  value,
  mult,
  ringColor,
  loading,
}: {
  index: number;
  value: string | null;
  mult: number;
  ringColor: string;
  loading: boolean;
}) {
  const size = { w: { xs: 92, md: 120 }, h: { xs: 92, md: 120 } } as const;

  const wiggle = {
    animate: loading
      ? {
          rotate: [0, -3, 3, 0],
          scale: [1, 1.02, 1],
          transition: { repeat: Infinity, duration: 2.4 },
        }
      : { rotate: 0, scale: 1 },
  };

  const flipVariants = {
    initial: { rotateX: -90, opacity: 0, scale: 0.9 },
    enter: {
      rotateX: 0,
      opacity: 1,
      scale: 1,
      transition: { type: 'spring', stiffness: 400, damping: 22, delay: index * 0.15 },
    },
    exit: { rotateX: 90, opacity: 0, scale: 0.95, transition: { duration: 0.18 } },
  };

  return (
    <Box
      sx={{
        width: { xs: size.w.xs, md: size.w.md },
        height: { xs: size.h.xs, md: size.h.md },
        borderRadius: '22px',
        position: 'relative',
        overflow: 'hidden',
        border: '2px solid #28476e',
        background: 'linear-gradient(180deg, #0b1a2b, #091524)',
        boxShadow:
          '0 0 20px rgba(120,180,255,.25), inset 0 0 30px rgba(20,40,80,.6), 0 12px 30px rgba(0,0,0,.35)',
        display: 'grid',
        placeItems: 'center',
        isolation: 'isolate',
      }}
      component={m.div}
      {...wiggle}
    >
      {/* halo tournant */}
      <Box
        sx={{
          position: 'absolute',
          inset: -10,
          borderRadius: '50%',
          background: `conic-gradient(from 0deg, transparent 0 35%, ${ringColor}44 40% 60%, transparent 65% 100%)`,
          animation: 'spin 10s linear infinite',
          filter: 'blur(10px)',
          zIndex: 0,
        }}
      />
      {/* sheen */}
      <Box
        sx={{
          position: 'absolute',
          inset: 0,
          background:
            'linear-gradient(110deg, transparent 0%, rgba(255,255,255,.05) 20%, rgba(255,255,255,.18) 40%, rgba(255,255,255,.05) 60%, transparent 100%)',
          backgroundSize: '200% 100%',
          animation: loading ? 'shine 2.6s linear infinite' : 'none',
          mixBlendMode: 'overlay',
          zIndex: 1,
        }}
      />
      {/* anneau */}
      <Box
        sx={{
          position: 'absolute',
          inset: 6,
          borderRadius: '18px',
          border: `2px solid ${ringColor}`,
          boxShadow: `inset 0 0 22px ${ringColor}33, 0 0 30px ${ringColor}22`,
          zIndex: 1,
          pointerEvents: 'none',
        }}
      />

      {/* ✨ Sparkles */}
      <Sparkles active={loading || !!value} color={ringColor} />

      {/* badge mult */}
      <Chip
        size="small"
        label={`x${mult}`}
        sx={{
          position: 'absolute',
          top: 6,
          right: 6,
          bgcolor: ringColor,
          color: '#03121f',
          fontWeight: 900,
          zIndex: 2,
          animation: loading ? 'pulse 2s ease-in-out infinite' : 'none',
        }}
      />

      {/* valeur */}
      <Box
        sx={{
          position: 'relative',
          zIndex: 2,
          perspective: 800,
          display: 'grid',
          placeItems: 'center',
          width: '100%',
          height: '100%',
        }}
      >
        <AnimatePresence mode="wait">
          {!value ? (
            <m.div
              key="pending"
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              transition={{ duration: 0.25 }}
              style={{
                fontWeight: 900,
                letterSpacing: 2,
                textShadow: '0 0 10px rgba(255,255,255,.15)',
                color: ringColor,
                fontSize: 'clamp(28px, 5vw, 36px)',
              }}
            >
              ??
            </m.div>
          ) : (
            <m.div
              key={value}
              variants={flipVariants}
              initial="initial"
              animate="enter"
              exit="exit"
              style={{
                fontWeight: 900,
                letterSpacing: 2,
                textShadow: '0 0 10px rgba(255,255,255,.15)',
                color: ringColor,
                fontSize: 'clamp(34px, 6vw, 44px)',
                transformStyle: 'preserve-3d',
              }}
            >
              {value}
            </m.div>
          )}
        </AnimatePresence>
      </Box>
    </Box>
  );
}

/* —— Mini système d’étincelles (sparks) —— */
function Sparkles({
  active,
  color = '#fff',
  count = 14,
}: {
  active: boolean;
  color?: string;
  count?: number;
}) {
  const particles = React.useMemo(() => {
    return Array.from({ length: count }).map((_, i) => {
      // répartition circulaire + jitter
      const angle = (i / count) * Math.PI * 2;
      const radius = 36 + Math.random() * 18;
      const x = Math.cos(angle) * radius;
      const y = Math.sin(angle) * radius;
      return {
        x,
        y,
        size: 2 + Math.random() * 3,
        delay: Math.random() * 1.2,
        dur: 1.1 + Math.random() * 0.9,
      };
    });
  }, [count]);

  return (
    <Box sx={{ position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 1 }}>
      {particles.map((p, idx) => (
        <m.span
          key={idx}
          initial={{ opacity: 0, scale: 0.6, x: 0, y: 0 }}
          animate={
            active
              ? {
                  opacity: [0, 1, 0],
                  scale: [0.6, 1, 0.8],
                  x: [0, p.x * 1.05, p.x],
                  y: [0, p.y * 1.05, p.y],
                  transition: {
                    repeat: Infinity,
                    duration: p.dur,
                    delay: p.delay,
                    ease: 'easeInOut',
                  },
                }
              : { opacity: 0 }
          }
          style={{
            position: 'absolute',
            left: '50%',
            top: '50%',
            width: p.size,
            height: p.size,
            borderRadius: 999,
            transform: 'translate(-50%, -50%)',
            background: `radial-gradient(circle at 50% 50%, ${color}, transparent 60%)`,
            filter: 'blur(0.2px)',
          }}
        />
      ))}
    </Box>
  );
}
